def max_num_edges_to_remove(n, edges):
    class DSU:
        def __init__(self, size):
            self.parent = list(range(size + 1))
            self.components = size

        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, a, b):
            root_a, root_b = self.find(a), self.find(b)
            if root_a == root_b:
                return False
            self.parent[root_a] = root_b
            self.components -= 1
            return True

    alice = DSU(n)
    bob = DSU(n)
    used = 0

    for t, u, v in edges:
        if t == 3:
            a_used = alice.union(u, v)
            b_used = bob.union(u, v)
            if a_used or b_used:
                used += 1

    for t, u, v in edges:
        if t == 1:
            if alice.union(u, v):
                used += 1
        elif t == 2:
            if bob.union(u, v):
                used += 1

    if alice.components != 1 or bob.components != 1:
        return -1

    return len(edges) - used

